package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Document struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Body  string `json:"body"`
	Owner string `json:"owner"`
}

// searchDocuments allows full-text search across documents
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	term := r.URL.Query().Get("q")
	owner := r.Header.Get("X-Authenticated-User")

	if owner == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	// Sanitize: remove semicolons to prevent statement stacking
	term = strings.ReplaceAll(term, ";", "")

	// Build query with owner filter for row-level access
	query := fmt.Sprintf(
		"SELECT id, title, body, owner FROM documents WHERE owner = '%s' AND (title ILIKE '%%%s%%' OR body ILIKE '%%%s%%') LIMIT 50",
		owner, term, term,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Body, &doc.Owner); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// getDocument retrieves a single document by ID (parameterized - safe)
func getDocument(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	owner := r.Header.Get("X-Authenticated-User")

	var doc Document
	err := db.QueryRow(
		"SELECT id, title, body, owner FROM documents WHERE id = $1 AND owner = $2",
		id, owner,
	).Scan(&doc.ID, &doc.Title, &doc.Body, &doc.Owner)

	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(doc)
}

// createDocument inserts a new document (parameterized - safe)
func createDocument(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var doc Document
	if err := json.NewDecoder(r.Body).Decode(&doc); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	owner := r.Header.Get("X-Authenticated-User")
	_, err := db.Exec(
		"INSERT INTO documents (title, body, owner) VALUES ($1, $2, $3)",
		doc.Title, doc.Body, owner,
	)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	w.WriteHeader(201)
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/get", getDocument)
	http.HandleFunc("/api/documents/create", createDocument)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
